/// <summary>
/// When <c>WhsWorkExecuteDisplayCanCatchWeightItemsUseExistingWorkFlight</c> is enabled,
/// ensure that for mobile device menu items with "Use existing work" enabled, the actual inventory weight from the inventory transactions is used instead of the average.
/// </summary>
internal final class WhsWorkExecuteDisplayCanCatchWeightItemsUseExistingWorkFlight extends Flight
{
    static private WhsWorkExecuteDisplayCanCatchWeightItemsUseExistingWorkFlight singleton = new WhsWorkExecuteDisplayCanCatchWeightItemsUseExistingWorkFlight();

}
